candidates.raw:
    adcs_quat_t norm_current, norm_target;
    adcs_quat_t q_curr_conj;
    adcs_quat_t q_rel;
    double w_rel;
    double clamped_w;
    double angle;
    double req_rate;
    double mrg;

    /* 1. Null checks */
    if ((current == NULL) || (target == NULL) || (required_rate == NULL) || (margin == NULL)) {
        return ADCS_E_NULL;
    }

    /* 2. Validate scalar inputs. Nonpositive duration or non-finite -> ADCS_E_RANGE */
    if ((!isfinite(max_rate)) || (!isfinite(duration)) || (duration <= 0.0)) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }

    /* 3. Normalize attitudes. Invalid quaternion -> ADCS_E_RANGE per requirement */
    if (adcs_quat_normalize(current, &norm_current) != ADCS_OK) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }
    if (adcs_quat_normalize(target, &norm_target) != ADCS_OK) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }

    /* 4. Compute relative quaternion: q_rel = target * conjugate(current) */
    q_curr_conj = adcs_quat_conjugate(&norm_current);
    q_rel = adcs_quat_multiply(&norm_target, &q_curr_conj);

    /* 5. Compute sign-invariant geodesic angle */
    w_rel = q_rel.w;

    /* Clamp absolute value of w to [0, 1] */
    if (w_rel < 0.0) {
        w_rel = -w_rel;
    }
    if (w_rel > 1.0) {
        w_rel = 1.0;
    } 
    /* w_rel is now in [0, 1] */

    /* Angle = 2 * acos(w_rel) */
    angle = 2.0 * acos(w_rel);

    /* 6. Compute required rate and margin */
    req_rate = angle / duration;
    mrg = max_rate - req_rate;

    /* 7. Assign outputs */
    *required_rate = req_rate;
    *margin = mrg;

    return ADCS_OK;
}

