candidates.raw:
    adcs_quat_t q_curr_norm, q_target_norm;
    adcs_quat_t q_curr_conj, q_rel;
    double w_rel_abs, w_clamped, angle, req_rate, marg;

    if ((current == NULL) || (target == NULL) || (required_rate == NULL) || (margin == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(max_rate)) || (max_rate < 0.0) || (!isfinite(duration)) || (duration <= 0.0)) {
        return ADCS_E_RANGE;
    }

    if (adcs_quat_normalize(current, &q_curr_norm) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    if (adcs_quat_normalize(target, &q_target_norm) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    q_curr_conj = adcs_quat_conjugate(&q_curr_norm);
    q_rel = adcs_quat_multiply(&q_target_norm, &q_curr_conj);

    w_rel_abs = fabs(q_rel.w);
    w_clamped = ADCS_CLAMP(w_rel_abs, 0.0, 1.0);

    angle = 2.0 * acos(w_clamped);
    req_rate = angle / duration;
    marg = max_rate - req_rate;

    *required_rate = req_rate;
    *margin = marg;

    return ADCS_OK;
}

